import sys

# Add large buffer for recursion limit
sys.setrecursionlimit(200000)

def is_lucky(n):
    """Check if n is a lucky number (only contains digits 4 and 7)"""
    s = str(n)
    return all(c in '47' for c in s)

def get_lucky_numbers(n):
    """Generate lucky numbers up to n"""
    lucky = []
    queue = ['4', '7']
    queue_idx = 0
    while queue_idx < len(queue) and int(queue[queue_idx]) <= n:
        num = int(queue[queue_idx])
        if num <= n:
            lucky.append(num)
        # Generate next numbers by appending 4 or 7
        if len(queue[queue_idx]) < 10:  # Safe limit for 10^5
            if not queue[queue_idx].endswith('4'):
                queue.append(queue[queue_idx] + '4')
            if not queue[queue_idx].endswith('7'):
                queue.append(queue[queue_idx] + '7')
        queue_idx += 1
    return lucky

def dfs(node, adj, visited, component_size):
    """DFS to find component size"""
    visited[node] = True
    count = 0
    stack = [node]
    while stack:
        curr = stack.pop()
        count += 1
        for neighbor in adj[curr]:
            if not visited[neighbor]:
                visited[neighbor] = True  # Mark before pushing to avoid duplicates
                stack.append(neighbor)
    return count

def solution(data):
    # Parse input
    lines = data.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        try:
            u, v = map(int, lines[i].split())
            adj[u].append(v)
            adj[v].append(u)
        except:
            break

    # Find connected components
    visited = [False] * (n + 1)
    component_sizes = []

    for i in range(1, n + 1):
        if not visited[i]:
            size = 1
            stack = [i]
            visited[i] = True
            while stack:
                curr = stack.pop()
                for neighbor in adj[curr]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
                        size += 1
            component_sizes.append(size)

    # Sort component sizes in descending order for better merging strategy
    component_sizes.sort(reverse=True)

    # Generate lucky numbers up to n
    lucky_numbers = get_lucky_numbers(n)

    # Check if any existing component is already lucky
    for size in component_sizes:
        if size in lucky_numbers:
            return '0\n'

    # DP to find minimum components needed for each lucky number
    # dp[sum] = minimum number of components to achieve this sum
    dp = {}

    for comp_size in component_sizes:
        # Update dp table
        new_dp = dp.copy()
        for s, count in dp.items():
            new_sum = s + comp_size
            if new_sum not in lucky_numbers or new_sum <= n:
                new_dp[new_sum] = min(new_dp.get(new_sum, float('inf')), count + 1)
                dp = new_dp.copy()

        # Check if this single component matches a lucky number
        if comp_size in lucky_numbers:
            dp[comp_size] = min(dp.get(comp_size, float('inf')), 1)

    # Find minimum roads needed
    min_roads = float('inf')
    for lucky in lucky_numbers:
        if lucky in dp:
            min_roads = min(min_roads, dp[lucky] - 1)

    if min_roads == float('inf'):
        return '-1\n'

    return f'{min_roads}\n'

# Test cases
if __name__ == "__main__":
    print(solution('4 3\n1 2\n2 3\n1 3\n'))  # Expected: 1
    print(solution('5 4\n1 2\n3 4\n4 5\n3 5\n'))  # Expected: -1
    print(solution('100000 1\n16796 47477\n'))  # Expected: 2
