            if len(parts) >= 2:
                b, z = map(int, parts[:2])
                mushrooms.append((b, z))

    total_expected_power = 0.0

    for m_b, m_z in mushrooms:
        survival_prob = 1.0
        for a, h, l, r in trees:
            hit_prob = 0.0

            # Check left fall: mushroom in [a - h, a)
            if l > 0 and a - h <= m_b < a:
                hit_prob += l / 100.0
            # Check right fall: mushroom in (a, a + h]
            elif r > 0 and a < m_b <= a + h:
                hit_prob += r / 100.0

            if hit_prob > 0:
                survival_prob *= (1 - hit_prob)

        total_expected_power += m_z * survival_prob

