    rev_map = {}
    for i in range(1, limit + 1):
        rev_map[i] = rev(i)

    # Group numbers by their reverse ratio: rev(a)/a
    # A ticket (a, b) is lucky if a * b == rev(a) * rev(b), which means rev(a)/a == rev(b)/b
    from fractions import Fraction

    groups = {}
    for i in range(1, maxx + 1):
        r = rev_map[i]
        if i == 0:
            continue
        ratio = Fraction(r, i)
        if ratio not in groups:
            groups[ratio] = []
        groups[ratio].append(i)

    for i in range(1, maxy + 1):
        r = rev_map[i]
        if i == 0:
            continue
        ratio = Fraction(r, i)
        if ratio not in groups:
            continue
        groups[ratio].append(i)

    # Create two collections: one for series (a), one for tickets (b)
    # Lucky count = sum over all ratios (count of a in ratio group) * (count of b in ratio group)

    # Actually, we can simplify: just for each a, count how many b satisfy the condition
    # But this is O(maxx * maxy) which is too slow

    # Alternative approach: for each ratio group in series, multiply by count in tickets
    # But we need to know which tickets would pair with which series

    # Better: Just count lucky tickets directly for candidate (x, y)
    # For small cases, this is acceptable

    # Try different (x, y) pairs, starting from small product
    best_x, best_y = -1, -1
    found = False

    # Sort by product to find minimum first
    for x in range(1, maxx + 1):
        if x * w > maxx * maxy and found:
            break
        for y in range(1, maxy + 1):
            if x * y > maxx * maxy and found:
                break
            if x * y > 1000000 and not found:  # limit search to avoid TLE
                break

            # Count lucky tickets
            lucky_count = 0
            for a in range(1, x + 1):
                ra = rev_map[a]
                for b in range(1, y + 1):
                    rb = rev_map[b]
                    if a * b == ra * rb:
                        lucky_count += 1

            if lucky_count >= w:
                # Found a valid (x, y)
                if best_x == -1 or x * y < best_x * best_y:
                    best_x, best_y = x, y
                    found = True
                break  # continue to larger x for potentially better product

    if found:
        return f"{best_x} {best_y}\n"
    else:
        # Try a smarter approach with only small x,y
        best_x, best_y = -1, -1
        for x in range(1, min(maxx, 200) + 1):
            for y in range(1, min(maxy, 200) + 1):
                lucky_count = 0
                for a in range(1, x + 1):
                    ra = rev_map[a]
                    for b in range(1, y + 1):
                        rb = rev_map[b]
                        if a * b == ra * rb:
                            lucky_count += 1

                if lucky_count >= w:
                    if best_x == -1:
                        best_x, best_y = x, y
        if best_x != -1:
            return f"{best_x} {best_y}\n"
        return "-1\n"
