import functools

def count_factors(n):
    """Count factors of 2 and 5 in a non-negative integer."""
    if n == 0:
        return 0, 0
    count2 = 0
    while n > 0 and n % 2 == 0:
        count2 += 1
        n //= 2
    count5 = 0
    while n > 0 and n % 5 == 0:
        count5 += 1
        n //= 5
    return count2, count5

def sort_key(p):
    """Sort key for Pareto filtering: prefer fewer 2s first, then fewer 5s."""
    return p[0] + p[1], p[0], p[1]

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    matrix = [list(map(int, line.split())) for line in lines[1:n+1]]

    @functools.lru_cache(None)
    def solve(i, j, p2, p5):
        """
        Returns (min_zeros, path_string) for reaching (i, j) with accumulated
        factor counts p2 of 2s and p5 of 5s.
        """
        if i == 0 and j == 0:
            return (0, "")

        min_zeros = float('inf')
        best_path = None

        from_top = (i > 0)
        from_left = (j > 0)

        candidates = []
        if from_top:
            zeros, path = solve(i - 1, j, p2, p5)
            candidates.append((zeros, path))
        if from_left:
            zeros, path = solve(i, j - 1, p2, p5)
            candidates.append((zeros, path))

        for zeros, path in candidates:
            total_zeros = min(p2, p5) + zeros
            if total_zeros < min_zeros:
                min_zeros = total_zeros
                best_path = path

        return (min_zeros, best_path)

    # Use iterative DP with state reduction to avoid recursion limits
    dp = [[[] for _ in range(n)] for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                c2, c5 = count_factors(matrix[i][j])
                if matrix[i][j] == 0:
                    dp[i][j].append((0, 0))
