        edges.append((u, v, w, i + 1))
        adj[u].append((v, w))
        adj[v].append((u, w))

    start = int(lines[1 + m])

    INF = float('inf')
    dist = [INF] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))

    total_weight = 0
    selected_edges = []

    for v in range(1, n + 1):
        if v == start:
            continue

        best_weight = INF
        best_idx = -1

        for u, w in adj[v]:
            if dist[u] != INF and dist[u] + w == dist[v]:
                if w < best_weight:
                    best_weight = w
                    # Find the edge index for this (u, v, w) pair
                    for idx, (eu, ev, ew, eidx) in enumerate(edges):
                        if eu == u and ev == v and ew == w:
                            best_idx = eidx
                            break

        if best_idx != -1:
            total_weight += best_weight
            selected_edges.append(best_idx)

    selected_edges.sort()
    return f"{total_weight}\n{' '.join(map(str, selected_edges))}"


