            if not (x1 < rix < x2):
                valid = False
        else:
            t_low = (x1 - rix) / vix
            t_high = (x2 - rix) / vix
            if vix > 0:
                t_min, t_max = t_low, t_high
            else:
                t_min, t_max = t_high, t_low

            if t_min >= t_max:
                valid = False
            else:
                mouse_min_t = max(mouse_min_t, t_min)
                mouse_max_t = min(mouse_max_t, t_max)

        # Y coordinate constraint: y1 < riy + viy*t < y2
        if valid:
            if viy == 0:
                if not (y1 < riy < y2):
                    valid = False
            else:
                t_low = (y1 - riy) / viy
                t_high = (y2 - riy) / viy
                if viy > 0:
                    t_min, t_max = t_low, t_high
                else:
                    t_min, t_max = t_high, t_low

                if t_min >= t_max:
                    valid = False
                else:
                    mouse_min_t = max(mouse_min_t, t_min)
                    mouse_max_t = min(mouse_max_t, t_max)

        if not valid:
            return "-1"

        # Need a valid non-negative interval
        if mouse_min_t >= mouse_max_t or mouse_max_t <= 0:
            return "-1"

        # Update global bounds
        global_min = max(global_min, mouse_min_t)
        global_max = min(global_max, mouse_max_t)

        if global_min >= global_max:
            return "-1"

    if global_max <= 0:
        return "-1"

    return f"{global_min:.10f}"
